-- ============================================================
-- Membership, redemption codes, Pomodoro totals (2026-11-27)
--
-- Plans: 'free' (default) and 'pro'. Pro is recorded only (no feature gating yet).
--   profiles.plan_expires_at = null with plan 'pro' means permanent.
-- Codes: one code, one account. Batch-generated by admins, optional expiry,
--   void unused codes, revoke redeemed ones (removes the granted days).
-- Pomodoro: completed focus minutes are logged per user; totals shown on the account.
-- ============================================================

alter table public.profiles add column if not exists plan text not null default 'free';
alter table public.profiles add column if not exists plan_expires_at timestamptz;
alter table public.profiles drop constraint if exists profiles_plan_check;
alter table public.profiles add constraint profiles_plan_check check (plan in ('free', 'pro'));

create table if not exists public.redeem_codes (
  id bigint generated by default as identity primary key,
  code text not null unique,
  batch text,
  plan text not null default 'pro' check (plan in ('pro')),
  days int check (days is null or days between 1 and 3650),   -- null = permanent
  note text,
  expires_at timestamptz,                                       -- code must be redeemed before this
  status text not null default 'active' check (status in ('active', 'redeemed', 'void', 'revoked')),
  redeemed_by uuid references auth.users (id) on delete set null,
  redeemed_at timestamptz,
  granted_until timestamptz,
  created_by text,
  created_at timestamptz not null default now()
);
create index if not exists redeem_codes_batch_idx on public.redeem_codes (batch);
create index if not exists redeem_codes_user_idx on public.redeem_codes (redeemed_by);
alter table public.redeem_codes enable row level security;
drop policy if exists "redeem_codes_admin" on public.redeem_codes;
create policy "redeem_codes_admin" on public.redeem_codes for select using (public.is_admin());

create table if not exists public.pomodoro_sessions (
  id bigint generated by default as identity primary key,
  user_id uuid not null references auth.users (id) on delete cascade,
  minutes int not null check (minutes between 1 and 180),
  mode text not null default 'focus' check (mode in ('focus', 'break')),
  completed_at timestamptz not null default now()
);
create index if not exists pomodoro_sessions_user_idx on public.pomodoro_sessions (user_id, completed_at desc);
alter table public.pomodoro_sessions enable row level security;
drop policy if exists "pomodoro_own_select" on public.pomodoro_sessions;
create policy "pomodoro_own_select" on public.pomodoro_sessions for select using (auth.uid() = user_id or public.is_admin());

-- ---------------------------------------------------------------- helpers
create or replace function public._plan_effective(p_plan text, p_expires timestamptz)
returns text
language sql
immutable
as $$
  select case when p_plan = 'pro' and (p_expires is null or p_expires > now()) then 'pro' else 'free' end;
$$;

-- Readable code: XXXX-XXXX-XXXX from an alphabet without 0/O/1/I/L.
create or replace function public._redeem_code_new()
returns text
language plpgsql
volatile
set search_path = public, extensions
as $$
declare
  alphabet constant text := 'ABCDEFGHJKMNPQRSTUVWXYZ23456789';
  b bytea := gen_random_bytes(12);
  s text := '';
  i int;
begin
  for i in 0..11 loop
    s := s || substr(alphabet, (get_byte(b, i) % length(alphabet)) + 1, 1);
    if i in (3, 7) then s := s || '-'; end if;
  end loop;
  return s;
end;
$$;

-- ---------------------------------------------------------------- user-facing
-- Redeem for the signed-in user. Extends an active Pro period instead of overwriting it.
create or replace function public.redeem_code(p_code text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
  v_code text := upper(regexp_replace(coalesce(p_code, ''), '[^A-Za-z0-9]', '', 'g'));
  c public.redeem_codes;
  p public.profiles;
  v_base timestamptz;
  v_until timestamptz;
begin
  if v_uid is null then raise exception '请先登录后再兑换' using errcode = '42501'; end if;
  if length(v_code) <> 12 then raise exception '兑换码格式不正确' using errcode = 'P0001'; end if;
  v_code := substr(v_code, 1, 4) || '-' || substr(v_code, 5, 4) || '-' || substr(v_code, 9, 4);

  -- Brute-force guard: at most 10 failed attempts per account per hour.
  if (select count(*) from public.security_events
        where user_id = v_uid and kind = 'redeem_failed' and created_at > now() - interval '1 hour') >= 10 then
    raise exception '尝试次数过多，请一小时后再试' using errcode = 'P0001';
  end if;

  select * into c from public.redeem_codes where code = v_code for update;
  if c.id is null or c.status <> 'active' or (c.expires_at is not null and c.expires_at < now()) then
    insert into public.security_events (kind, user_id, detail) values ('redeem_failed', v_uid, jsonb_build_object('code_tail', right(v_code, 4)));
    raise exception '%', case
      when c.id is null then '兑换码不存在'
      when c.status = 'redeemed' then '该兑换码已被使用'
      when c.status in ('void', 'revoked') then '该兑换码已失效'
      else '该兑换码已过期' end using errcode = 'P0001';
  end if;

  select * into p from public.profiles where id = v_uid for update;
  if p.plan = 'pro' and p.plan_expires_at is null then
    v_until := null;                                   -- already permanent
  elsif c.days is null then
    v_until := null;                                   -- permanent code
  else
    v_base := case when p.plan = 'pro' and p.plan_expires_at > now() then p.plan_expires_at else now() end;
    v_until := v_base + make_interval(days => c.days);
  end if;

  update public.profiles set plan = 'pro', plan_expires_at = v_until where id = v_uid;
  update public.redeem_codes
     set status = 'redeemed', redeemed_by = v_uid, redeemed_at = now(), granted_until = v_until
   where id = c.id;
  insert into public.security_events (kind, user_id, detail) values ('redeem', v_uid, jsonb_build_object('code_tail', right(v_code, 4), 'days', c.days));

  return jsonb_build_object('plan', 'pro', 'expires_at', v_until, 'days', c.days);
end;
$$;

create or replace function public.my_account()
returns jsonb
language sql
stable
security definer
set search_path = public, auth
as $$
  select jsonb_build_object(
    'email', u.email,
    'created_at', u.created_at,
    'last_sign_in_at', u.last_sign_in_at,
    'email_confirmed_at', u.email_confirmed_at,
    'display_name', p.display_name,
    'locale', p.locale,
    'exam_zone', p.exam_zone,
    'country', p.country,
    'plan', public._plan_effective(p.plan, p.plan_expires_at),
    'plan_expires_at', case when p.plan = 'pro' then p.plan_expires_at end,
    'pomodoro', jsonb_build_object(
      'total_minutes', coalesce((select sum(minutes) from public.pomodoro_sessions where user_id = u.id and mode = 'focus'), 0),
      'sessions', (select count(*) from public.pomodoro_sessions where user_id = u.id and mode = 'focus'),
      'week_minutes', coalesce((select sum(minutes) from public.pomodoro_sessions where user_id = u.id and mode = 'focus' and completed_at > now() - interval '7 days'), 0),
      'today_minutes', coalesce((select sum(minutes) from public.pomodoro_sessions where user_id = u.id and mode = 'focus'
                                   and (completed_at at time zone 'Asia/Shanghai')::date = (now() at time zone 'Asia/Shanghai')::date), 0)
    ),
    'redemptions', coalesce((select jsonb_agg(jsonb_build_object('code_tail', right(code, 4), 'days', days, 'redeemed_at', redeemed_at, 'granted_until', granted_until, 'status', status) order by redeemed_at desc)
                               from public.redeem_codes where redeemed_by = u.id), '[]'::jsonb)
  )
  from auth.users u join public.profiles p on p.id = u.id
  where u.id = auth.uid();
$$;

create or replace function public.update_my_profile(p_display_name text)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v text := nullif(left(trim(coalesce(p_display_name, '')), 40), '');
begin
  if auth.uid() is null then raise exception '请先登录' using errcode = '42501'; end if;
  if v is null then raise exception '昵称不能为空' using errcode = 'P0001'; end if;
  update public.profiles set display_name = v where id = auth.uid();
  return public.my_account();
end;
$$;

-- Log a completed Pomodoro block (called by the timer when a block finishes).
create or replace function public.log_pomodoro(p_minutes int, p_mode text default 'focus')
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_uid uuid := auth.uid();
begin
  if v_uid is null then return jsonb_build_object('logged', false); end if;
  if p_minutes is null or p_minutes < 1 or p_minutes > 180 then return jsonb_build_object('logged', false); end if;
  -- One block cannot finish faster than its own length: reject bursts.
  if exists (select 1 from public.pomodoro_sessions
              where user_id = v_uid and completed_at > now() - make_interval(mins => greatest(p_minutes - 1, 1))) then
    return jsonb_build_object('logged', false, 'reason', 'too_soon');
  end if;
  insert into public.pomodoro_sessions (user_id, minutes, mode) values (v_uid, p_minutes, case when p_mode = 'break' then 'break' else 'focus' end);
  return jsonb_build_object('logged', true);
end;
$$;

-- ---------------------------------------------------------------- admin
create or replace function public.admin_redeem_create(p_count int, p_days int, p_expires_at timestamptz default null, p_note text default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  v_batch text := to_char(now() at time zone 'Asia/Shanghai', 'YYYYMMDD-HH24MISS');
  v_codes text[] := '{}';
  v_code text;
  i int;
begin
  perform public._admin_guard();
  if p_count is null or p_count < 1 or p_count > 500 then raise exception '一次生成 1–500 个'; end if;
  if p_days is not null and (p_days < 1 or p_days > 3650) then raise exception '天数需在 1–3650 之间，留空表示永久'; end if;
  for i in 1..p_count loop
    loop
      v_code := public._redeem_code_new();
      begin
        insert into public.redeem_codes (code, batch, days, note, expires_at, created_by)
        values (v_code, v_batch, p_days, nullif(left(trim(coalesce(p_note, '')), 80), ''), p_expires_at, auth.jwt() ->> 'email');
        exit;
      exception when unique_violation then
        -- astronomically unlikely; try another code
      end;
    end loop;
    v_codes := v_codes || v_code;
  end loop;
  perform public._admin_audit('redeem.create', v_batch, jsonb_build_object('count', p_count, 'days', p_days, 'expires_at', p_expires_at));
  return jsonb_build_object('batch', v_batch, 'codes', to_jsonb(v_codes));
end;
$$;

create or replace function public.admin_redeem_list(p_status text default null, p_search text default null, p_limit int default 500)
returns jsonb
language plpgsql
stable
security definer
set search_path = public
as $$
declare
  v_q text := nullif(upper(trim(coalesce(p_search, ''))), '');
begin
  perform public._admin_guard();
  return jsonb_build_object(
    'items', coalesce((
      select jsonb_agg(jsonb_build_object(
               'id', c.id, 'code', c.code, 'batch', c.batch, 'days', c.days, 'note', c.note,
               'expires_at', c.expires_at,
               'status', case when c.status = 'active' and c.expires_at is not null and c.expires_at < now() then 'expired' else c.status end,
               'redeemed_by', c.redeemed_by, 'redeemed_email', u.email, 'redeemed_at', c.redeemed_at,
               'granted_until', c.granted_until, 'created_by', c.created_by, 'created_at', c.created_at
             ) order by c.created_at desc, c.id desc)
        from (select * from public.redeem_codes
               where (p_status is null or p_status = 'all' or status = p_status
                      or (p_status = 'expired' and status = 'active' and expires_at < now()))
                 and (v_q is null or code like '%' || v_q || '%' or coalesce(batch, '') like '%' || v_q || '%' or upper(coalesce(note, '')) like '%' || v_q || '%')
               order by created_at desc, id desc
               limit greatest(1, least(coalesce(p_limit, 500), 2000))) c
        left join auth.users u on u.id = c.redeemed_by), '[]'::jsonb),
    'counts', (select jsonb_build_object(
                 'active', count(*) filter (where status = 'active' and (expires_at is null or expires_at >= now())),
                 'redeemed', count(*) filter (where status = 'redeemed'),
                 'expired', count(*) filter (where status = 'active' and expires_at < now()),
                 'void', count(*) filter (where status in ('void', 'revoked')),
                 'pro_members', (select count(*) from public.profiles where public._plan_effective(plan, plan_expires_at) = 'pro'))
               from public.redeem_codes),
    'generated_at', now()
  );
end;
$$;

-- Void an unused code, or revoke a redeemed one (takes back the days it granted).
create or replace function public.admin_redeem_void(p_id bigint)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
declare
  c public.redeem_codes;
  p public.profiles;
  v_new timestamptz;
begin
  perform public._admin_guard();
  select * into c from public.redeem_codes where id = p_id for update;
  if c.id is null then raise exception '兑换码不存在'; end if;
  if c.status = 'active' then
    update public.redeem_codes set status = 'void' where id = p_id;
  elsif c.status = 'redeemed' then
    select * into p from public.profiles where id = c.redeemed_by for update;
    if p.id is not null then
      if c.days is null then
        -- permanent grant revoked: back to free unless other active codes keep them Pro
        v_new := (select max(granted_until) from public.redeem_codes where redeemed_by = p.id and status = 'redeemed' and id <> c.id);
        update public.profiles set plan = case when v_new > now() then 'pro' else 'free' end, plan_expires_at = v_new where id = p.id;
      elsif p.plan_expires_at is not null then
        v_new := p.plan_expires_at - make_interval(days => c.days);
        update public.profiles set plan = case when v_new > now() then 'pro' else 'free' end,
                                   plan_expires_at = case when v_new > now() then v_new end
         where id = p.id;
      end if;
    end if;
    update public.redeem_codes set status = 'revoked' where id = p_id;
  end if;
  perform public._admin_audit('redeem.void', c.code, jsonb_build_object('previous', c.status, 'user', c.redeemed_by));
  return jsonb_build_object('id', p_id, 'status', (select status from public.redeem_codes where id = p_id));
end;
$$;

-- Admin: set a user's plan directly (e.g. support cases).
create or replace function public.admin_set_plan(p_user uuid, p_plan text, p_expires_at timestamptz default null)
returns jsonb
language plpgsql
volatile
security definer
set search_path = public
as $$
begin
  perform public._admin_guard();
  if p_plan not in ('free', 'pro') then raise exception 'invalid plan'; end if;
  update public.profiles set plan = p_plan, plan_expires_at = case when p_plan = 'pro' then p_expires_at end where id = p_user;
  perform public._admin_audit('plan.set', p_user::text, jsonb_build_object('plan', p_plan, 'expires_at', p_expires_at));
  return jsonb_build_object('plan', p_plan, 'expires_at', p_expires_at);
end;
$$;

-- Security events: allow the new kinds.
create or replace function public.log_security_event(p_kind text, p_email text default null, p_detail jsonb default '{}'::jsonb)
returns void
language plpgsql
volatile
security definer
set search_path = public
as $$
begin
  if p_kind not in ('sign_in', 'sign_in_failed', 'sign_out', 'sign_up', 'password_reset_requested', 'password_changed') then
    return;
  end if;
  if (select count(*) from public.security_events
        where ip = public._req_ip() and created_at > now() - interval '10 minutes') >= 30 then
    return;
  end if;
  insert into public.security_events (kind, email, user_id, ip, user_agent, detail)
  values (p_kind, left(lower(p_email), 200), auth.uid(), left(public._req_ip(), 64), left(public._req_header('user-agent'), 400),
          case when jsonb_typeof(p_detail) = 'object' then p_detail else '{}'::jsonb end);
  delete from public.security_events where created_at < now() - interval '180 days';
end;
$$;

-- ---------------------------------------------------------------- grants
revoke all on function public._redeem_code_new() from public, anon, authenticated;
revoke all on function public._plan_effective(text, timestamptz) from public, anon, authenticated;
revoke all on function public.redeem_code(text) from public, anon;
revoke all on function public.my_account() from public, anon;
revoke all on function public.update_my_profile(text) from public, anon;
revoke all on function public.log_pomodoro(int, text) from public, anon;
revoke all on function public.admin_redeem_create(int, int, timestamptz, text) from public, anon;
revoke all on function public.admin_redeem_list(text, text, int) from public, anon;
revoke all on function public.admin_redeem_void(bigint) from public, anon;
revoke all on function public.admin_set_plan(uuid, text, timestamptz) from public, anon;
grant execute on function public.redeem_code(text) to authenticated;
grant execute on function public.my_account() to authenticated;
grant execute on function public.update_my_profile(text) to authenticated;
grant execute on function public.log_pomodoro(int, text) to authenticated;
grant execute on function public.admin_redeem_create(int, int, timestamptz, text) to authenticated;
grant execute on function public.admin_redeem_list(text, text, int) to authenticated;
grant execute on function public.admin_redeem_void(bigint) to authenticated;
grant execute on function public.admin_set_plan(uuid, text, timestamptz) to authenticated;

notify pgrst, 'reload schema';
